const $guide=(id)=>document.getElementById(id);
const guides={
'&I':['두 문장 P와 Q에서 P & Q를 도출합니다. 순서는 바꾸어 Q & P로 해도 됩니다.','P / Q','P & Q','1,2'],
'&E':['P & Q에서 P 또는 Q 중 하나를 도출합니다.','P & Q','Q','1'],
'vI':['P에서 임의의 Q를 선언지로 더해 P v Q 또는 Q v P를 도출합니다.','P','P v Q','1'],
'vE':['선언 P v Q와 선언지 하나의 부정 ~P가 있으면 남은 Q를 도출합니다. 양쪽 선언지 순서는 바꾸어도 됩니다. 두 선언지를 각각 가정해 같은 결론을 얻는 경우 분석은 이 강의의 vE가 아닙니다.','P v Q / ~P','Q','1,2'],
'->I':['P를 가정하고 그 범위에서 Q를 도출하면 P → Q를 씁니다. 근거는 가정 시작-마지막 줄 범위입니다.','P 가정 / Q 도출','P → Q','1-2'],
'->E':['P → Q와 P에서 Q를 도출합니다. 이를 전건 긍정이라고도 부릅니다.','P → Q / P','Q','1,2'],
'~I':['P를 가정하고 Q와 ~Q에서 ⊥를 도출하면 P 가정을 해제하고 ~P를 씁니다. 근거는 시작-끝 범위입니다. 수업에서는 모순을 먼저 ⊥I로 명시합니다.','P 가정 / … / ⊥','~P','1-4'],
'~E':['수업 표기의 ~E는 부정 제거, 즉 ~~P에서 바깥 부정 두 개를 제거해 P를 얻는 규칙입니다. Q와 ~Q에서 ⊥를 만들 때 쓰는 규칙이 아닙니다.','~~P','P','1'],
'<->I':['P → Q와 Q → P를 모두 보이면 P ↔ Q를 도입합니다. 또는 P 가정에서 Q까지의 범위와 Q 가정에서 P까지의 범위 두 개를 인용합니다.','P → Q / Q → P','P ↔ Q','1,2 또는 1-2,3-4'],
'<->E':['수업 자료의 쌍조건문 제거는 P ↔ Q에서 P → Q 또는 Q → P를 꺼냅니다. P ↔ Q와 P만으로 Q를 한 번에 쓰는 규칙은 아닙니다.','P ↔ Q','P → Q','1'],
'⊥I':['문장 P와 그 부정 ~P가 모두 있으면 ⊥를 도출합니다. 수업의 모순 도입 규칙입니다. 반대 근거 순서도 됩니다.','Q / ~Q','⊥','2,4'],
'R':['열린 상위 범위의 문장은 하위 보조 증명 안으로 가져와 반복할 수 있습니다. 닫힌 하위 증명의 문장은 바깥으로 반복해 꺼낼 수 없습니다.','P','P','1'],
'가정':['조건문·부정·쌍조건문을 도입하기 위한 임시 보조 증명을 엽니다. 근거는 비워둡니다. 적절한 도입 규칙으로 가정을 해제하세요.','새 가정 P','P','빈칸'],
'DN':['P에서 이중부정 ~~P를 도입합니다. ~E의 반대 방향입니다.','P','~~P','1'],
'MT':['P → Q와 ~Q에서 ~P를 도출하는 후건 부정 규칙입니다. 두 번째 줄은 Q의 부정이어야 합니다.','P → Q / ~Q','~P','1,2'],
'CA':['P → Q와 Q → R에서 P → R을 도출하는 연쇄 논법입니다. 가운데 Q가 맞닿아야 합니다.','P → Q / Q → R','P → R','1,2'],
'CP':['P → Q에서 대우 ~Q → ~P를 도출합니다.','P → Q','~Q → ~P','1'],
'W':['이미 얻은 Q에서 P → Q를 도출합니다. P 가정에서 Q를 반복해 조건문을 도입하는 파생 규칙입니다.','Q','P → Q','1'],
'AC':['P v Q, P → R, Q → R에서 R을 도출합니다. 양쪽 경우가 같은 R로 이어져야 합니다. 수업에서는 파생 규칙입니다. 기본 규칙 vE는 한 선언지의 부정에서 다른 선언지를 얻습니다.','P v Q / P → R / Q → R','R','1,2,3'],
'CR':['P v Q와 Q v P의 교환을 허용합니다. 수업 자료의 정리 표기를 한 줄의 파생 규칙으로 적용합니다.','P v Q','Q v P','1'],
'AR':['선언의 괄호 위치를 P v (Q v R)와 (P v Q) v R 사이에서 바꿉니다.','P v (Q v R)','(P v Q) v R','1'],
'DR':['연언과 선언의 분배를 양방향으로 허용합니다. 분배법칙 두 식 모두 적용합니다.','P & (Q v R)','(P & Q) v (P & R)','1'],
'DM':['부정된 선언 ~ (P v Q)와 부정된 연언 ~(P & Q)을 각각 드모르간 동치식으로 변환합니다.','~(P v Q)','~P & ~Q','1'],
'C':['P → Q를 ~P v Q로, ~(P → Q)를 P & ~Q로 바꾸는 조건문 파생 규칙입니다. 부분식 안에서도 적용할 수 있습니다.','P → Q','~P v Q','1']};
const rows=Logic.ruleInfo.map(([id,name,short,group])=>{let [desc,from,to,refs]=guides[id];return `<details class="rule-detail" ${['⊥I','~I','~E','vE','<->E'].includes(id)?'open':''}><summary><b>${id}</b><span>${esc(name)}</span><small>${esc(short)}</small></summary><div class="rule-detail-body"><p>${esc(desc)}</p><dl class="rule-inputs"><div><dt>전제 줄 예시</dt><dd><code>${esc(from)}</code></dd></div><div><dt>다음 명제</dt><dd><code>${esc(to)}</code></dd></div><div><dt>근거 줄</dt><dd><code>${esc(refs)}</code></dd></div></dl><p class="guide-rule-group">${group==='basic'?'기본 규칙 · 핸드아웃 4':group==='derived'?'파생 규칙 · 핸드아웃 5':'증명 보조 규칙'}</p></div></details>`}).join('');$guide('ruleGuide').innerHTML=rows;
